cd /app/corpus && python3 << 'EOF'
import os

# Let me get values from FFO-3 table - these are the annual totals 
years = range(2011, 2021)

dod_data = []

for year in years:
    filename = f'treasury_bulletin_{year}_09.txt'
    if not os.path.exists(filename):
        print(f"File not found: {filename}")
        continue

    with open(filename, 'r') as f:
        lines = f.readlines()

    # Look in the FFO-3 table (after "TABLE FFO-3")
    in_ff03 = False
    for i, line in enumerate(lines):
        if 'FFO-3' in line and 'On-Budget and Off-Budget' in line:
            in_ff03 = True
        if in_ff03 and f'| {year} |' in line and 'Est' not in line:
            # Found the row with just the year (like "2011")
            parts = line.split('|')
            # Column for DoD (index 5 in the row, but need to account for empty first element)
            if len(parts) >= 6:
                try:
                    val = parts[5].strip().replace(',', '')
                    if val:
                        value = float(val)
                        if value > 100000:
                            print(f"FY {year}: Found value {value}")
                            dod_data.append((year, value))
                            break
                except Exception as e:
                    pass

print("\n\nDoD outlays from FFO-3:")
for year, val in dod_data:
    print(f"FY {year}: ${val:,.0f}")
EOF
